e next step with someone who's walked it.";const typedCount=ref(0);const reducedMotion=ref(false);const segmentText=text=>typeof Intl!=='undefined'&&'Segmenter' in Intl?Array.from(new Intl.Segmenter(undefined,{granularity:'grapheme'}).segment(text),part=>part.segment):Array.from(text);let observer;let typeTimer;let motionMedia
onMounted(()=>{motionMedia=window.matchMedia('(prefers-reduced-motion: reduce)');const updateMotion=()=>{reducedMotion.value=motionMedia.matches;if(reducedMotion.value)typedCount.value=segmentText(heroText).length};updateMotion();motionMedia.addEventListener('change',updateMotion);if(!reducedMotion.value){const segments=segmentText(heroText);let index=0;const typeNext=()=>{index+=1;typedCount.value=index;if(index<segments.length){const latest=segments[index-1];typeTimer=window.setTimeout(typeNext,/[.!?]/.test(latest)?260:latest===','?120:34)}};requestAnimationFrame(typeNext)};roleTimer=window.setInterval(()=>{if(!rolePaused.value){if(roleStep.value<4)roleStep.value+=1;else{roleStep.value=0;role.value=roleNames[(roleNames.indexOf(role.value)+1)%roleNames.length]}}},4000);observer=new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>Math.abs(a.boundingClientRect.top-window.innerHeight*.46)-Math.abs(b.boundingClientRect.top-window.innerHeight*.46))[0];if(visible)currentSection.value=visible.target.dataset.section},{rootMargin:'-20% 0px -50% 0px'});document.querySelectorAll('[data-section]').forEach(el=>observer.observe(el))})
