 direction</strong><div class="chip-row"><button v-for="(a,i) in areas.slice(0,3)" :key="a[0]" :class="{selected:active===i}" @click="active=i">{{a[0]}}</button></div></div><div class="fragment mentor-fragment"><div class="silhouette"><span></span><small>Mentor · Higher-studies background</small></div><div class="chip-row"><span class="reason-chip">Matched on {{areas[active][0]}}</span><span class="reason-chip">Available</span></div></div></div></section>
